			if (megaMenuText == target.text()) {
				text += megaMenuText;
			} else {
				text += megaMenuText + " - " + subTitleText + " - " + target.text();
			}
		} else if (target.text() == "") {
			text += megaMenuText;
		} else {
			text += target.text();
		}
		if (!text.length) {
			text = "N/A";
		}
